const patientById=id=>db.patients.find(p=>p.id===id),currentPatient=()=>patientById(selectedPatientId)||db.patients[0],patientRows=k=>(db[k]||[]).filter(r=>r.patientId===currentPatient()?.id||(!r.patientId&&r.patient===currentPatient()?.name));
function sessionFinancials(record={}){
  const grossAmount=Math.max(0,+record.amount||0),discountPercent=Math.max(0,Math.min(100,+record.discountPercent||0)),discountAmount=grossAmount*discountPercent/100,amount=Math.max(0,grossAmount-discountAmount),paid=Math.max(0,Math.min(+record.paidAmount||0,amount));
  let clinicShare=Math.max(0,+record.clinicShare||0),doctorShare=Math.max(0,+record.doctorShare||0);
  if(record.splitMode==='نسبة مئوية'){
    const clinicPercent=Math.max(0,Math.min(100,+record.clinicPercent||0));
    clinicShare=amount*clinicPercent/100;doctorShare=amount-clinicShare;
  }else if(amount>0&&clinicShare+doctorShare===0){clinicShare=amount;doctorShare=0}
  const shareTotal=clinicShare+doctorShare,clinicRatio=shareTotal?clinicShare/shareTotal:0,doctorRatio=shareTotal?doctorShare/shareTotal:0;
  const clinicCollected=Math.min(clinicShare,paid*clinicRatio),doctorCollected=Math.min(doctorShare,paid*doctorRatio);
  return{grossAmount,discountPercent,discountAmount,amount,paid,remainingAmount:Math.max(0,amount-paid),clinicShare,doctorShare,clinicCollected,doctorCollected,clinicOutstanding:Math.max(0,clinicShare-clinicCollected),doctorOutstanding:Math.max(0,doctorShare-doctorCollected)};
}
function withSessionFinancials(record={}){const f=sessionFinancials(record);return{...record,amount:f.grossAmount.toFixed(2),discountPercent:String(f.discountPercent),discountAmount:f.discountAmount.toFixed(2),netAmount:f.amount.toFixed(2),paidAmount:f.paid.toFixed(2),remainingAmount:f.remainingAmount.toFixed(2),clinicShare:f.clinicShare.toFixed(2),doctorShare:f.doctorShare.toFixed(2),clinicCollected:f.clinicCollected.toFixed(2),doctorCollected:f.doctorCollected.toFixed(2),clinicOutstanding:f.clinicOutstanding.toFixed(2),doctorOutstanding:f.doctorOutstanding.toFixed(2)}}
function normalizeRecord(k,data,old={}){if(data.patientId){const p=patientById(data.patientId);data.patient=p?.name||old.patient||'';if(k==='finance'&&!data.person)data.person=data.patient}if(k==='sessions'){if(!data.number)data.number=String(db.sessions.filter(s=>s.patientId===data.patientId).length+1);const financials=sessionFinancials(data);if(data.splitMode==='نسبة مئوية'){const amount=financials.amount,clinicPercent=Math.max(0,Math.min(100,+data.clinicPercent||0));data.clinicPercent=String(clinicPercent);data.clinicShare=(amount*clinicPercent/100).toFixed(2);data.doctorShare=(amount-(+data.clinicShare||0)).toFixed(2)}data=withSessionFinancials(data)}return data}
