const stat=(label,value,note='')=>`<div class="stat"><small>${label}</small><strong>${esc(value)}</strong><span>${esc(note)}</span></div>`;
function dashboard(){if(!remoteReady)return '<div class="empty"><b>◷</b>جارٍ تحميل البيانات المحفوظة من قاعدة ORAVENA…</div>';if(role==='patient')return patientHome();const todaySessions=db.sessions.filter(x=>x.date===today()&&x.status!=='ملغاة'),todayMoney=accountTotals(todaySessions);return `<div class="stats compact-stats">${stat('طلبات الكشف',db.appointments.filter(x=>x.status==='كشف').length,'تحتاج مراجعة')}${stat('ملفات المرضى',db.patients.length,'ملفات محفوظة')}${stat('تحصيل اليوم',money(todayMoney.paid),`متبقي ${money(todayMoney.remaining)}`)}${stat('خطط نشطة',db.plans.filter(x=>x.status==='نشطة').length,'قيد المتابعة')}</div>${todaySessions.length?`<div class="notice finance-ready"><div><b>ملف حسابات اليوم جاهز</b><span>العيادة حصّلت ${money(todayMoney.clinicCollected)} · الدكتور حصّل ${money(todayMoney.doctorCollected)}</span></div><button class="mini" id="dailyFinanceExport">تصدير حسابات اليوم PDF</button></div>`:''}<div class="grid-2"><div class="panel"><div class="panel-head"><h2>طلبات الكشف الواردة</h2><span class="badge warn">${db.appointments.length} طلب</span></div>${table('appointments',db.appointments.slice(0,8),true)}</div><div class="panel"><h2>إجراءات سريعة</h2><div class="quick-actions"><button data-new="schedule">＋ موعد في الأجندة</button><button data-new="patients">＋ ملف مريض</button><button data-go="patients">فتح ملفات المرضى</button><button data-go="accounts">فتح الحسابات</button><button data-go="services">إدارة الخدمات</button></div><h3>آخر العمليات</h3><ul class="activity">${db.audit.slice(0,5).map(x=>`<li><b>${esc(x.action)}</b><small>${esc(x.date)} · ${esc(x.user)}</small></li>`).join('')}</ul></div></div>`}
function patientHome(){const p=currentPatient();if(!p)return '<div class="empty">لا يوجد ملف مريض.</div>';const ap=patientRows('appointments').filter(x=>!['ملغي','مكتمل'].includes(x.status))[0],plan=patientRows('plans')[0],last=patientRows('sessions')[0],pt=patientMoney(p.id);return `<div class="notice patient-switch">ملف المريض <select id="familySwitch">${db.patients.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${esc(x.name)} — ${esc(x.file)}</option>`).join('')}</select></div><div class="stats">${stat('الموعد القادم',ap?.date||'بانتظار التحديد',ap?.time||ap?.status||'')}${stat('تقدم العلاج',(plan?.progress||0)+'%',plan?.title||'لا توجد خطة')}${stat('المبلغ المتبقي',money(pt.due),pt.due?'غير مدفوع بالكامل':'مسدد')}${stat('الجلسات',patientRows('sessions').length,last?.status||'')}</div><div class="grid-2"><div class="panel"><div class="panel-head"><h2>العلاج الحالي</h2><span class="badge ok">${esc(plan?.status||'لا توجد خطة')}</span></div><h3>${esc(plan?.title||'لم تُضف خطة بعد')}</h3><p class="muted">الخطوة القادمة: ${esc(plan?.nextStep||'يحددها الطبيب')}</p><div class="progress-bar"><i style="width:${Math.min(100,+plan?.progress||0)}%"></i></div><div class="quick-actions"><button data-go="appointments">المواعيد</button><button data-go="patientRecord">فتح ملفي الطبي</button></div></div><div class="panel"><h2>آخر جلسة</h2><p>${esc(last?.visible||'لا توجد جلسات مسجلة.')}</p><h3>الحساب</h3><p>المدفوع: <b>${money(pt.paid)}</b> · المتبقي: <b>${money(pt.due)}</b></p></div></div>`}
function patientAccount(){const p=currentPatient();if(!p)return '<div class="empty">جارٍ تجهيز ملف حسابك…</div>';return `<div class="panel account-panel"><div class="panel-head"><div><p class="dialog-kicker">ORAVENA CARE</p><h2>بيانات حسابي</h2></div><span class="badge ok">محفوظة وآمنة</span></div><p class="muted">تُحفظ البيانات في حسابك وتظهر على أي جهاز عند الدخول بنفس الحساب.</p><form id="myAccountForm" class="form-grid"><label>رقم الملف<input value="${esc(p.file)}" disabled></label><label>الاسم الكامل<input name="name" value="${esc(p.name)}" required></label><label>رقم الهاتف<input name="phone" value="${esc(p.phone)}" type="tel"></label><label>رقم الهوية<input name="nationalId" value="${esc(p.nationalId)}"></label><label>السن<input name="age" value="${esc(p.age)}" type="number" min="0" max="120"></label><label>تاريخ الميلاد<input name="birth" value="${esc(p.birth)}" type="date"></label><div class="dialog-actions wide"><button class="primary" type="submit">حفظ بيانات حسابي</button></div></form></div>`}
function visibleRows(k){let rows=db[k]||[];if(role==='patient')rows=patientRows(k).map(x=>k==='sessions'?Object.fromEntries(Object.entries(x).filter(([key])=>key!=='internal')):x);if(filter){const f=filter.toLowerCase();rows=rows.filter(x=>Object.values(x).some(v=>String(v).toLowerCase().includes(f)))}return rows}
const statusBadge=v=>String(v||'').includes('ملغ')?'danger':String(v||'').match(/كشف|بدأ|تنفيذ/) ?'warn':'ok';
function table(k,rows=visibleRows(k),actions=true){const d=defs[k];if(!rows.length)return '<div class="empty"><b>⌕</b>لا توجد سجلات</div>';const moneyFields=['price','amount','netAmount','paidAmount','remainingAmount','clinicShare','doctorShare','clinicCollected','doctorCollected','clinicOutstanding','doctorOutstanding'];return `<div class="table-wrap"><table class="data-table"><thead><tr>${Object.values(d.cols).map(v=>`<th>${v}</th>`).join('')}${actions?'<th>الإجراءات</th>':''}</tr></thead><tbody>${rows.map(r=>`<tr>${Object.keys(d.cols).map(c=>`<td>${c==='status'?`<span class="badge ${statusBadge(r[c])}">${esc(r[c])}</span>`:c==='permissions'?esc(String(r[c]||'').split(',').map(x=>sectionLabels[x]||x).join('، ')):moneyFields.includes(c)?money(r[c]):c==='discountPercent'?`${esc(r[c]||0)}%`:c==='fileName'&&r.fileData?`<button class="mini" data-preview="${r.id}">${esc(r.fileName||'فتح الصورة')}</button>`:esc(r[c])}</td>`).join('')}${actions?`<td><div class="row-actions">${k==='patients'?`<button class="mini" data-patient="${r.id}">فتح الملف</button>`:''}${k==='finance'&&r.type==='فاتورة علاج'?`<button class="mini" data-invoice="${r.id}">الفاتورة</button>`:''}${role!=='patient'&&k==='sessions'&&!['بدأت','مكتملة'].includes(r.status)?`<button class="mini start" data-start="${r.id}">بدء الجلسة</button>`:''}${role!=='patient'?`<button class="mini edit" data-edit="${k}:${r.id}">تعديل</button><button class="mini delete" data-delete="${k}:${r.id}">حذف</button>`:''}</div></td>`:''}</tr>`).join('')}</tbody></table></div>`}
function patientFinance(){const p=currentPatient();if(!p)return '<div class="empty">لا يوجد ملف مريض.</div>';const rows=patientRows('finance').filter(x=>x.status==='معتمدة'),totals=financeTotals(rows),invoices=rows.filter(x=>x.type==='فاتورة علاج');return `<div class="patient-balance">${stat('إجمالي المدفوع',money(totals.paid),'الدفعات بعد خصم أي استرداد')}${stat('المبلغ المتبقي',money(totals.due),totals.due?'مطلوب سداده':'الحساب مسدد')}</div><div class="panel invoice-list"><div class="panel-head"><div><p class="dialog-kicker">تفاصيل العلاج</p><h2>فواتير ${esc(p.name)}</h2></div><span class="muted">${invoices.length} فاتورة</span></div>${invoices.length?invoices.map(invoice=>`<article class="invoice-row"><div><strong>${esc(invoice.treatment||invoice.person||'علاج أسنان')}</strong><small>${esc(invoice.date||'')}</small></div><b>${money(invoice.amount)}</b><button class="secondary" data-invoice="${invoice.id}">عرض التفاصيل</button></article>`).join(''):'<div class="empty">لا توجد فواتير علاج معتمدة حتى الآن.</div>'}</div>`}
function patientCards(){
  const f=filter.trim().toLowerCase();
  const rows=db.patients.filter(p=>(!f||[p.name,p.file,p.phone,p.age].some(v=>String(v||'').toLowerCase().includes(f)))&&(!patientAgeFilter||String(p.age)===patientAgeFilter));
  return `<div class="patient-files-toolbar"><label>تصفية حسب السن<input id="patientAgeFilter" type="number" min="0" max="120" value="${esc(patientAgeFilter)}" placeholder="السن"></label><span>${rows.length} ملف</span></div>${rows.length?`<div class="patient-card-grid">${rows.map(p=>`<button class="patient-file-card" data-patient="${p.id}" type="button"><img src="assets/oravena-icon-new.png" alt=""><span class="patient-file-number">${esc(p.file||'ملف مريض')}</span><strong>${esc(p.name)}</strong><small>${esc(p.age||'غير محدد')} سنة${p.phone?` · ${esc(p.phone)}`:''}</small><i>فتح الملف ←</i></button>`).join('')}</div>`:'<div class="empty"><b>⌕</b>لا توجد ملفات مطابقة للبحث أو السن.</div>'}`;
}
function serviceParentName(service){return service?.parentServiceId?(db.services.find(x=>x.id===service.parentServiceId)?.nameAr||'—'):'—'}
function dayLabel(date){const value=new Date(date+'T12:00:00'),nowDate=new Date(today()+'T12:00:00'),diff=Math.round((value-nowDate)/86400000);if(diff===0)return 'اليوم';if(diff===1)return 'غدًا';if(diff===-1)return 'أمس';return value.toLocaleDateString('ar-EG',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}
function schedulePage(){const rows=[...db.schedule].sort((a,b)=>`${a.date} ${a.time}`.localeCompare(`${b.date} ${b.time}`)),groups=rows.reduce((all,row)=>((all[row.date]??=[]).push(row),all),{}),yesterday=dateKey(new Date(Date.now()-86400000)),hasYesterday=Boolean(groups[yesterday]?.length);return `${hasYesterday?`<div class="notice schedule-archive"><div><b>سجل مواعيد أمس ما زال موجودًا</b><span>هل تريد حفظه PDF قبل إزالته من الأجندة؟</span></div><div><button class="mini" data-archive-day="${yesterday}:yes">نعم، حفظ PDF</button><button class="mini delete" data-archive-day="${yesterday}:no">لا، إزالة فقط</button></div></div>`:''}<div class="schedule-board">${Object.entries(groups).map(([date,items])=>`<section class="schedule-day ${date<today()?'past':''}"><header><div><small>${dayLabel(date)}</small><h2>${esc(date)}</h2></div><span>${items.length} حالات</span></header><div class="schedule-cases">${items.map(item=>{const important=item.important||db.sessions.some(s=>s.patientId===item.patientId&&s.important);return `<article class="schedule-case ${important?'important':''}"><time>${esc(item.time)}</time><div><strong>${esc(item.patient)}</strong><small>${esc(item.service||'غير محدد')}</small></div>${important?'<span class="important-mark">مهم</span>':''}<span class="badge ${statusBadge(item.status)}">${esc(item.status)}</span><div class="row-actions"><button class="mini edit" data-edit="schedule:${item.id}">تعديل</button><button class="mini delete" data-delete="schedule:${item.id}">حذف</button></div></article>`}).join('')}</div></section>`).join('')||'<div class="empty"><b>◷</b>ابدأ بإضافة مواعيد يومك.</div>'}</div>`}
function accountsPage(){
  const rows=db.sessions.filter(x=>x.status!=='ملغاة'&&(!accountsDate||x.date===accountsDate)).map(withSessionFinancials);
  const totals=accountTotals(rows);
  return `<div class="accounts-toolbar panel"><label>حسابات يوم<input id="accountsDate" type="date" value="${esc(accountsDate)}"></label><button class="secondary" id="accountsAllDates" type="button">كل الأيام</button><button class="primary" id="accountsExport" type="button">تصدير الحسابات PDF</button></div><div class="stats account-summary">${stat('إجمالي الخدمات',money(totals.amount),`${rows.length} جلسة`)}${stat('المحصّل فعليًا',money(totals.paid))}${stat('المتبقي على المرضى',money(totals.remaining))}${stat('محصل العيادة',money(totals.clinicCollected),`متبقي ${money(totals.clinicOutstanding)}`)}${stat('محصل الدكتور',money(totals.doctorCollected),`متبقي ${money(totals.doctorOutstanding)}`)}</div><div class="panel"><div class="panel-head"><div><p class="dialog-kicker">توزيع التحصيل</p><h2>${accountsDate?`حسابات ${dayLabel(accountsDate)}`:'كل الحسابات'}</h2></div><span class="badge ${totals.remaining?'warn':'ok'}">${totals.remaining?'توجد مبالغ متبقية':'المبالغ مسددة'}</span></div>${rows.length?`<div class="table-wrap"><table class="data-table account-ledger"><thead><tr><th>المريض</th><th>الخدمة</th><th>التاريخ</th><th>التكلفة</th><th>المدفوع</th><th>المتبقي</th><th>العيادة: محصل / متبقي</th><th>الدكتور: محصل / متبقي</th><th>الحالة</th></tr></thead><tbody>${rows.map(row=>{const f=sessionFinancials(row);return `<tr><td>${esc(row.patient||patientById(row.patientId)?.name||'—')}</td><td>${esc(row.service||row.type||'غير محدد')}</td><td>${esc(row.date||'—')}</td><td>${money(f.amount)}</td><td>${money(f.paid)}</td><td class="${f.remainingAmount?'amount-due':'amount-paid'}">${money(f.remainingAmount)}</td><td><b>${money(f.clinicCollected)}</b><small>متبقي ${money(f.clinicOutstanding)}</small></td><td><b>${money(f.doctorCollected)}</b><small>متبقي ${money(f.doctorOutstanding)}</small></td><td><span class="badge ${statusBadge(row.status)}">${esc(row.status||'—')}</span></td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty"><b>₺</b>لا توجد جلسات مالية في التاريخ المحدد.</div>'}</div>`;
}
function listPage(k){if(k==='patients')return patientCards();if(k==='appointments')return schedulePage();if(k==='services'){db.services.forEach(s=>s.parentName=serviceParentName(s));return `<div class="service-hierarchy-summary"><span>${db.services.filter(s=>s.serviceType==='رئيسية').length} خدمات رئيسية</span><span>${db.services.filter(s=>s.serviceType==='فرعية').length} خدمات فرعية</span></div><div class="panel"><div class="panel-head"><h2>الخدمات الرئيسية والفرعية</h2><span class="muted">${db.services.length} خدمة</span></div>${table('services')}</div>`}return `<div class="panel"><div class="panel-head"><h2>${sectionLabels[k]}</h2><span class="muted">${visibleRows(k).length} سجل</span></div>${table(k)}</div>`}
function accountRows(patientId){
  const sessions=db.sessions.filter(x=>x.patientId===patientId&&x.status!=='ملغاة'&&((+x.amount||0)>0||(+x.paidAmount||0)>0));
  if(!sessions.length)return '<div class="empty">لا توجد مبالغ مسجلة على الجلسات.</div>';
  return `<div class="session-account-list">${sessions.map(x=>{const f=sessionFinancials(x);return `<article><div><strong>${esc(x.service||x.type||'خدمة أسنان')}</strong><small>${esc(x.date||'')} · الجلسة ${esc(x.number||'—')}</small></div><span>السعر <b>${money(f.grossAmount)}</b>${f.discountPercent?` · خصم ${esc(f.discountPercent)}%`:''}</span><span>المطلوب <b>${money(f.amount)}</b></span><span>المدفوع <b>${money(f.paid)}</b></span><span class="${f.remainingAmount?'due':'paid'}">${f.remainingAmount?'المتبقي':'مسدد'} <b>${money(f.remainingAmount)}</b></span></article>`}).join('')}</div>`;
}
function recordActivity(p){
  const rows=[...patientRows('appointments').map(x=>({date:x.updatedAt||x.createdAt||x.date,label:`موعد: ${x.service||'غير محدد'} — ${x.status}`})),...patientRows('sessions').map(x=>({date:x.createdAt||x.date,label:`جلسة ${x.number||''}: ${x.status||'غير محدد'}`})),...patientRows('plans').map(x=>({date:x.createdAt||x.expiry,label:`خطة علاج: ${x.title||'غير محدد'}`}))].sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))).slice(0,5);
  return rows.length?`<ul class="patient-timeline">${rows.map(x=>`<li><i></i><div><strong>${esc(x.label)}</strong><small>${esc(String(x.date||'').slice(0,10))}</small></div></li>`).join('')}</ul>`:'<div class="empty">لا توجد عمليات مسجلة بعد.</div>';
}
function recordAccordion(key,title,content,p,open=false){const canAdd=role!=='patient'&&['appointments','sessions','imaging','plans'].includes(key);return `<details class="record-accordion" ${open?'open':''}><summary><span>${title}</span><small>${(db[key]||[]).filter(x=>x.patientId===p.id).length} سجل</small></summary><div class="record-accordion-body">${canAdd?`<div class="record-section-actions"><button class="mini" data-new-for="${key}:${p.id}">＋ إضافة</button></div>`:''}${content}</div></details>`}
const patientPanelMeta={sessions:{title:'الجلسات',icon:'✚'},plans:{title:'خطة العلاج',icon:'☷'},odontogram:{title:'خريطة الأسنان',icon:'◉'},account:{title:'حساب المريض',icon:'₺'}};
function patientPanelButton(key,p,moneyData){const meta=patientPanelMeta[key],active=activePatientPanel===key,count=key==='odontogram'?'32 سنًا':key==='account'?`المتبقي ${money(moneyData.due)}`:`${(db[key]||[]).filter(x=>x.patientId===p.id).length} سجل`;return `<button class="patient-panel-icon ${active?'active':''}" data-patient-panel="${key}" type="button" aria-pressed="${active}" title="${active?'اضغط مرتين للإغلاق':'فتح '+meta.title}"><i>${meta.icon}</i><strong>${meta.title}</strong><small>${count}</small></button>`}
function patientPanelContent(key,p,moneyData,patientMode){
  if(key==='sessions')return `${patientMode?'':`<div class="record-section-actions"><button class="mini" data-new-for="sessions:${p.id}">＋ إضافة جلسة</button></div>`}${table('sessions',patientRows('sessions'),!patientMode)}`;
  if(key==='plans')return `${patientMode?'':`<div class="record-section-actions"><button class="mini" data-new-for="plans:${p.id}">＋ إضافة خطة</button></div>`}${table('plans',patientRows('plans'),!patientMode)}`;
  if(key==='odontogram')return odontogram(true);
  if(key==='account')return `<div class="patient-balance">${stat('إجمالي تكلفة الجلسات',money(moneyData.cost))}${stat('إجمالي المدفوع',money(moneyData.paid))}${stat('المبلغ المتبقي',money(moneyData.due),moneyData.due?'مطلوب سداده':'الحساب مسدد')}</div>${accountRows(p.id)}`;
  return '';
}
function patientRecord(){
  const p=currentPatient();if(!p)return '<div class="empty">لم يتم العثور على المريض.</div>';
  const moneyData=patientMoney(p.id),patientMode=role==='patient';
  const panelKeys=Object.keys(patientPanelMeta),panel=activePatientPanel&&patientPanelMeta[activePatientPanel]?`<section class="patient-panel-view" data-open-panel="${activePatientPanel}"><header><span>${patientPanelMeta[activePatientPanel].icon}</span><div><small>ملف ${esc(p.name)}</small><h2>${patientPanelMeta[activePatientPanel].title}</h2></div></header><div class="patient-panel-content">${patientPanelContent(activePatientPanel,p,moneyData,patientMode)}</div></section>`:'';
  return `<div class="record-hero patient-file-hero"><img src="assets/oravena-icon-new.png" alt=""><div><small>${esc(p.file)}</small><h2>${esc(p.name)}</h2><p>${esc(p.age||'غير محدد')} سنة${p.phone?` · ${esc(p.phone)}`:''}</p></div>${patientMode?'':`<div class="record-actions"><button class="secondary" data-edit="patients:${p.id}">تعديل البيانات</button></div>`}</div><div class="profile-grid simple-profile">${[['السن',`${p.age||'غير محدد'} سنة`],['الهاتف',p.phone],['رقم الهوية',p.nationalId],['تاريخ الميلاد',p.birth],['المبلغ المتبقي',money(moneyData.due)]].map(x=>`<div><small>${x[0]}</small><b>${esc(x[1]||'غير مسجل')}</b></div>`).join('')}</div><div class="panel recent-patient-activity"><div class="panel-head"><h2>آخر العمليات المسجلة</h2></div>${recordActivity(p)}</div><div class="record-stack">${recordAccordion('appointments','المواعيد',table('appointments',patientRows('appointments'),!patientMode),p,true)}</div><div class="patient-panel-shell ${activePatientPanel?'is-open':'is-idle'}"><nav class="patient-panel-dock" aria-label="أقسام ملف المريض">${panelKeys.map(key=>patientPanelButton(key,p,moneyData)).join('')}</nav>${panel}</div>`;
}
function completeTeethMap(saved={}){const complete=blankTeeth();for(const [number,value] of Object.entries(saved||{})){if(complete[number])complete[number]={...complete[number],...(value&&typeof value==='object'?value:{})}}return complete}
function odontogram(compact=false){const p=currentPatient();if(!p)return '<div class="empty">أضف مريضًا أولًا.</div>';const teeth=completeTeethMap(db.teeth[p.id]);db.teeth[p.id]=teeth;return `${compact?'':`<div class="patient-context"><label>خريطة المريض <select id="toothPatient">${db.patients.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${esc(x.name)} — ${esc(x.file)}</option>`).join('')}</select></label><span>مرّر على السن لعرض حالته، واضغط لفتح ملفه</span></div>`}<div class="clinical-odontogram"><div class="odontogram-stage"><img src="assets/oravena-adult-odontogram.png" alt="خريطة تشريحية لفكي وأسنان شخص بالغ، 32 سنًا" draggable="false"><span class="arch-label upper">الفك العلوي · 1–16</span><span class="arch-label lower">الفك السفلي · 17–32</span>${toothPositions.map(([n,x,y,w,h])=>tooth(n,teeth[n],x,y,w,h)).join('')}</div><div class="legend"><span><i class="healthy"></i>سليم</span><span><i class="caries"></i>تسوس</span><span><i class="treated"></i>معالج</span><span><i class="implant"></i>زراعة</span><span><i class="missing"></i>مفقود</span><span><i class="planned"></i>مخطط</span></div><p class="odontogram-note">الترقيم وفق النظام العالمي للأسنان الدائمة. الألوان توضّح الحالة المسجلة لكل سن.</p></div>`}
function tooth(n,t,x,y,w,h){t={status:'healthy',stage:'',needs:'',note:'',history:[],...(t&&typeof t==='object'?t:{})};const history=(Array.isArray(t.history)?t.history:[]).slice(-12).map(h=>`${String(h.date||'').slice(0,10)}: ${statusName(h.status)} — ${h.stage||'بدون مرحلة'}`).join('\n');const tip=`السن ${n} — ${statusName(t.status)}\nالمرحلة: ${t.stage||'غير مسجلة'}\nيحتاج: ${t.needs||'لا يوجد'}\nالتفاصيل: ${t.note||'لا توجد تفاصيل'}${history?'\nسجل سابق:\n'+history:''}`;return `<button class="tooth-hotspot ${t.status}" style="--x:${x}%;--y:${y}%;--w:${w}%;--h:${h}%" data-tooth="${n}" aria-label="${esc(tip)}"><span class="tooth-state"></span><b>${n}</b><span class="tooth-tip">${esc(tip).replaceAll('\n','<br>')}</span></button>`}
